145	        } else {
146	            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
147	        }
148	
149	        // OrderBid 조회
150	        try {
151	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
152	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
153	
154	            if (orderBid != null) {
155	                Sale sale = orderBid.getSale();
156	                if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
157	                    log.info("OrderBid 기반 Sale 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
158	                            orderBid.getId(), sale.getId());
159	
160	                    sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
161	
162	                    // 판매자에게 알림 생성
163	                    User seller = sale.getSeller();
164	                    notificationCommandService.createNotification(
165	                            seller.getId(),
166	                            NotificationCategory.SHOPPING,
167	                            NotificationType.BID,
168	                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
169	                    );
170	
171	                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
172	                            seller.getId(), sale.getId());
173	                } else {
174	                    log.debug("Sale 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
175	                }
176	            }
177	        } catch (IllegalArgumentException e) {
178	            log.warn("OrderBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());
179	            // OrderBid가 없는 경우 예외로 중단하지 않고 진행
180	        }
