185	    /**
186	     * HTML에서 배송 상태를 파싱합니다.
187	     *
188	     * @param html 파싱할 HTML 문자열
189	     * @param trackingNumber 로깅용 운송장 번호
190	     * @return 배송 상태 문자열
191	     * @throws ShipmentException 파싱 실패 시 발생
192	     */
193	    private String parseStatusFromHtml(String html, String trackingNumber) {
194	        try {
195	            Document doc = Jsoup.parse(html);
196	            Elements rows = doc.select(STATUS_SELECTOR);
197	
198	            if (rows.isEmpty()) {
199	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
200	                throw new ShipmentException(
201	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
202	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
203	                );
204	            }
205	
206	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
207	            String statusText = rows.last().select("td").get(4).text().trim();
208	
209	            if (statusText.isEmpty()) {
210	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
211	                throw new ShipmentException(
212	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
213	                        "배송 상태 정보를 찾을 수 없습니다."
214	                );
215	            }
216	
217	            return statusText;
218	
219	        } catch (IndexOutOfBoundsException e) {
220	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
221	            throw new ShipmentException(
222	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
223	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
224	                    e
225	            );
226	        } catch (Exception e) {
227	            if (e instanceof ShipmentException) {
228	                throw (ShipmentException) e;
229	            }
230	
231	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
232	            throw new ShipmentException(
233	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
234	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
235	                    e
236	            );
237	        }
238	    }
