241	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
242	     *
243	     * @param statusText 배송사 상태 텍스트
244	     * @return 매핑된 ShipmentStatus
245	     */
246	    private ShipmentStatus mapToShipmentStatus(String statusText) {
247	        return switch (statusText) {
248	            case "배송완료" -> ShipmentStatus.DELIVERED;
249	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
250	            default -> ShipmentStatus.IN_TRANSIT;
251	        };
252	    }
