    86	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
    87	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
    88	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
    89	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
    90	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
    91	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
