303	    private void sendRealTimeNotification(String email, NotificationDTO notification) {
304	        String redisKey = REDIS_KEY_PREFIX + email;
305	
306	        // 연결된 사용자에게만 알림 전송
307	        if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
308	            try {
309	                messagingTemplate.convertAndSendToUser(
310	                        email,
311	                        WEBSOCKET_DESTINATION,
312	                        notification
313	                );
314	                log.debug("알림 실시간 전송 완료: 사용자={}, 알림ID={}", email, notification.getId());
315	            } catch (Exception e) {
316	                log.warn("알림 실시간 전송 실패: 사용자={}, 알림ID={}, 오류={}",
317	                        email, notification.getId(), e.getMessage());
318	                // 실시간 전송 실패해도 알림은 이미 저장되었으므로 예외 발생시키지 않음
319	            }
320	        } else {
321	            log.debug("사용자 WebSocket 연결 없음: 사용자={}, 알림은 저장됨", email);
322	        }
323	    }
